-- Reviewable inventory of Gather functionality that already exists in the
-- product or in an approved module brief. These records intentionally remain
-- Draft / Needs review: an administrator must approve scope and evidence in
-- the Module Planner before the analyzer includes them in a scoring baseline.

INSERT OR IGNORE INTO planner_modules
  (id,module_code,name,description,purpose,functional_requirements,acceptance_criteria,status,priority,owner_name,target_release,risk_level,progress,approval_state,created_by,created_at,updated_at)
VALUES
  ('module-identity-access','GR-AUTH','Identity & Role Access','Authentication, account recovery, role routing, and organization-scoped access.','Give organizers, bidders, platform administrators, and fulfillment managers the correct secure workspace.','Supabase authentication; confirmation and password recovery; explicit role routing; organization membership checks; protected administrator routes.','Users reach the correct role workspace, unauthorized cross-organization access is denied, and recovery links return to the configured environment.','Needs review','Critical','Gather Product','Launch','Critical',0,'Draft','system',1795587116912,1795587116912),
  ('module-adaptive-onboarding','GR-ONBOARD','Adaptive Event Onboarding','Five-step guided setup for online, live, and hybrid fundraising events.','Let an organizer create a useful event draft quickly while revealing advanced controls only when relevant.','Organization; Event Details; Add Items; Payments & Delivery; Review & Launch; autosave; event-type adaptation; actionable launch validation.','A new organizer can create a draft, understand every blocking validation issue, launch an eligible event, and resume without re-entering account information.','Needs review','Critical','Gather Product','Launch','High',0,'Draft','system',1795587116912,1795587116912),
  ('module-auction-page-builder','GR-PAGE','Auction Page Builder','Organizer-controlled branded public auction pages with responsive previews.','Help each nonprofit publish a credible, shareable fundraising destination without custom development.','Logo and banner; colors; page copy; shareable URL; mobile and desktop preview; draft and publish states.','Draft changes remain private until published, public pages use the approved content, and previews accurately represent responsive output.','Needs review','High','Gather Product','Launch','Medium',0,'Draft','system',1795587116912,1795587116912),
  ('module-auction-bidding','GR-AUCTION','Auction Catalog & Bidding','Items, bidder registration, watchlists, maximum bidding, Buy Now, and auction-close behavior.','Provide reliable mobile-first silent auctions for nonprofits and supporters.','Item catalog; categories and images; donor and FMV fields; increments; maximum bids; tie handling; anti-sniping; watchlists; My Bids; Buy Now.','Authorized bidders can bid safely, invalid bids are rejected, concurrent bids remain consistent, and winners are determined from durable records.','Needs review','Critical','Gather Product','Launch','Critical',0,'Draft','system',1795587116912,1795587116912),
  ('module-payments-checkout','GR-PAY','Winner Checkout & Payments','Stripe Connect onboarding, combined winner invoices, checkout, receipts, refunds, and reconciliation.','Collect winning-bid payments securely while keeping Gather free for nonprofit organizers.','Stripe Connect; invoice totals; processor-fee disclosure; optional Gather support; hosted checkout; signed webhooks; idempotency; receipts; refunds.','Gather platform fee remains $0, optional support can remain $0, processor costs are separate, and duplicate webhooks never duplicate settlement.','Needs review','Critical','Gather Product','Launch','Critical',0,'Draft','system',1795587116912,1795587116912),
  ('module-event-settlement','GR-SETTLE','Event Closeout & Financial Records','Organizer closeout, obligation tracking, reconciliation, exports, and retained event records.','Give nonprofits a complete, understandable record of what happened after an event.','Winner obligations; invoice and payment status; item pickup and shipping; refunds; exceptions; reconciliation; exports; closeout lock and audit history.','Organizer totals reconcile to authoritative transactions, unresolved obligations remain visible, and closeout preserves immutable financial history.','Needs review','High','Gather Product','Launch','Critical',0,'Draft','system',1795587116912,1795587116912),
  ('module-give-holidays','GR-TRAVEL','Give Holidays Catalog & Fulfillment','Controlled travel catalog, auction-item integration, payment-gated claims, and booking fulfillment.','Provide optional risk-free travel experiences without making travel a condition of using Gather.','Private master catalog; locked package terms; organizer selection; bidder presentation; sold-package tracking; traveler claims; fulfillment statuses.','Internal cost remains private, fulfillment begins only after payment, inventory is controlled, and the nonprofit can use Gather without a travel package.','Needs review','High','Gather Product','Launch','High',0,'Draft','system',1795587116912,1795587116912),
  ('module-ticketing','GR-TICKETS','Tickets, Tables & Check-in','Ticket design, sales, guest records, tables, QR admission, and event check-in.','Support fundraising-event attendance without weakening the auction experience.','Ticket types and bundles; table reservations; designer; checkout; guest assignment; QR codes; check-in; attendance records.','Capacity and order totals remain consistent, QR admission is single-use and auditable, and organizer records identify purchasers and guests.','Needs review','Medium','Gather Product','Post-launch','High',0,'Draft','system',1795587116912,1795587116912),
  ('module-sponsors','GR-SPONSORS','Event Sponsors','Sponsor records, invitations, benefits, branding, commitments, and fulfillment.','Help nonprofits organize sponsor relationships and show approved recognition across event experiences.','Sponsor levels; contacts; invitations; commitments; benefits; assets; page placement; payment and fulfillment status.','Only approved sponsor assets are public, benefits and commitments are traceable, and sponsor revenue is not double counted.','Needs review','Medium','Gather Product','Post-launch','Medium',0,'Draft','system',1795587116912,1795587116912),
  ('module-gather-live','GR-LIVE','Gather Live','Live auction, Fund-a-Need, paddle, operator, and projector workflows.','Support controlled in-room fundraising after the online silent-auction foundation is dependable.','Live session states; paddles; lots; appeal levels; operator controls; projector display; pledges; payment handoff.','Only authorized operators control the session, state changes are durable, projector failures stop safely, and every pledge enters reconciliation.','Needs review','Medium','Gather Product','Post-launch','Critical',0,'Draft','system',1795587116912,1795587116912),
  ('module-direct-offers','GR-OFFERS','Give Holidays Direct Fundraising Offers','Standalone travel fundraising offers outside a traditional auction.','Give nonprofits an optional, clearly priced way to raise funds through curated travel offers.','Offer pages; eligibility and terms; nonprofit attribution; purchase records; payment gate; claims; fulfillment; reporting.','Offer economics are disclosed, travel remains optional, paid purchases create fulfillment obligations exactly once, and nonprofit attribution is durable.','Needs review','Medium','Gather Product','Post-launch','High',0,'Draft','system',1795587116912,1795587116912),
  ('module-messaging','GR-MSG','In-app Messaging & Notifications','Organizer-supporter conversations and event communications with consent-aware delivery.','Keep operational questions and relevant fundraising communication attached to the correct organization and event.','Threads; participants; unread state; moderation; in-app notices; transactional email handoff; notification preferences.','Messages are organization-scoped, recipients control optional notifications, transactional events remain distinct from marketing, and abuse can be handled.','Needs review','Medium','Gather Product','Post-launch','High',0,'Draft','system',1795587116912,1795587116912),
  ('module-org-settings','GR-SETTINGS','Organization Settings, Email & Receipts','Organization identity, contacts, sender settings, receipt content, and operational preferences.','Let each nonprofit manage durable organization-wide information separately from individual events.','Organization profile; contact email; branding; sender identity; receipt settings; authorized members; defaults.','Account email and organization contact remain distinct, settings are organization-scoped, and receipt changes are reflected only where appropriate.','Needs review','High','Gather Product','Launch','High',0,'Draft','system',1795587116912,1795587116912),
  ('module-security-records','GR-SECURITY','Security, Audit & Records Integrity','Security controls, immutable audit evidence, data retention, and operational monitoring.','Protect nonprofit and supporter information while preserving trustworthy financial and administrative history.','Authorization; secure headers; rate limits; audit events; retention rules; backups; restore evidence; secret separation; security alerts.','Sensitive access is denied by default, material actions are auditable, protected records cannot be silently rewritten, and recovery procedures are verified.','Needs review','Critical','Gather Product','Launch','Critical',0,'Draft','system',1795587116912,1795587116912),
  ('module-sandbox-testing','GR-SANDBOX','Sandbox Testing Center','Isolated staging configuration, test roles, issue reporting, fixtures, and release evidence.','Let Gather be exercised end to end without affecting production users, money, email, or travel fulfillment.','Separate Sites project; staging Supabase and D1; Stripe test mode; test email sink; seeded roles; issue reports; TEST MODE indicator.','Sandbox credentials cannot reach production resources, test actions have no real-world consequence, and verified results can be linked to planner tasks.','Needs review','Critical','Gather Product','Launch','Critical',0,'Draft','system',1795587116912,1795587116912);

INSERT OR IGNORE INTO planner_features
  (id,module_id,name,description,functional_specification,acceptance_criteria,status,approval_state,created_by,created_at,updated_at)
VALUES
  ('auth-feature-role-routing','module-identity-access','Role-based landing and navigation','Route each account to the correct workspace.','Resolve organization membership and privileged roles on the server before rendering protected navigation.','Organizer, bidder, platform administrator, and fulfillment manager test accounts land in their intended workspace.','Needs review','Draft','system',1795587116912,1795587116912),
  ('auth-feature-recovery','module-identity-access','Verification and password recovery','Branded email links and secure callback handling.','Use environment-specific allowed redirects and preserve the intended return route.','Confirmation and recovery links succeed without localhost or cross-environment redirects.','Needs review','Draft','system',1795587116912,1795587116912),
  ('onboard-feature-five-steps','module-adaptive-onboarding','Five-step guided setup','One primary action per autosaved step.','Organization, Event Details, Add Items, Payments & Delivery, and Review & Launch adapt to the selected event type.','Draft state survives navigation and existing users do not repeat completed organization setup.','Needs review','Draft','system',1795587116912,1795587116912),
  ('onboard-feature-validation','module-adaptive-onboarding','Actionable launch validation','Explain exactly what prevents launch.','Return field- and step-level validation with a direct path to correct each issue.','A generic launch failure is never shown when a specific correction is known.','Needs review','Draft','system',1795587116912,1795587116912),
  ('page-feature-builder','module-auction-page-builder','Brand and content builder','Responsive structured page editing and preview.','Support images, logo, color, campaign copy, shareable URL, mobile preview, desktop preview, and publish state.','Published pages render the last approved published revision on mobile and desktop.','Needs review','Draft','system',1795587116912,1795587116912),
  ('auction-feature-bidding','module-auction-bidding','Maximum bidding and anti-sniping','Transaction-safe bid placement and close extensions.','Enforce increments, earlier-bid ties, private maximums, and the approved anti-sniping window.','Concurrent and retry scenarios do not produce invalid leaders or duplicate writes.','Needs review','Draft','system',1795587116912,1795587116912),
  ('auction-feature-bidder-home','module-auction-bidding','Bidder home, watchlist, and My Bids','Mobile-first discovery and personal bid status.','Expose catalog search, item details, watchlist, leading/outbid state, My Bids, My Wins, and notifications without leaking private maximums.','A supporter sees only their own private bid and win information.','Needs review','Draft','system',1795587116912,1795587116912),
  ('payment-feature-invoices','module-payments-checkout','Combined winner invoices','One auditable invoice across eligible winning items.','Calculate winning bids, shipping or pickup, processor disclosure, optional Gather support, payments, refunds, and balance due.','Platform fee is always zero and nonprofit proceeds exclude optional Gather support.','Needs review','Draft','system',1795587116912,1795587116912),
  ('payment-feature-webhooks','module-payments-checkout','Signed idempotent payment lifecycle','Stripe event intake and durable state transitions.','Verify signatures, claim events atomically, retry failures safely, and reconcile refunds and disputes.','Duplicate or reordered events cannot create duplicate payment or fulfillment records.','Needs review','Draft','system',1795587116912,1795587116912),
  ('settle-feature-closeout','module-event-settlement','Closeout workspace','Resolve and preserve post-event obligations.','Show paid and unpaid winners, pickup, shipping, refunds, exceptions, follow-up status, and closeout readiness.','An organizer can export complete records and cannot close an event with hidden unresolved blockers.','Needs review','Draft','system',1795587116912,1795587116912),
  ('travel-feature-catalog','module-give-holidays','Master travel catalog','Private package management and safe organizer selection.','Support package content, pricing, floors, availability, restrictions, locked terms, and public-safe presentation.','Nonprofits and bidders never see internal cost or supplier-only information.','Needs review','Draft','system',1795587116912,1795587116912),
  ('travel-feature-fulfillment','module-give-holidays','Payment-gated travel fulfillment','Claim and booking status trail after payment.','Create one fulfillment after successful payment and track traveler details, date requests, booking, confirmation, fulfillment, cancellation, and refund.','No bid alone creates a travel cost or supplier obligation.','Needs review','Draft','system',1795587116912,1795587116912),
  ('ticket-feature-designer','module-ticketing','Ticket types and designer','Create event-specific ticket inventory and branded admission records.','Support individual tickets, bundles, tables, pricing, availability, and buyer-facing preview.','Published ticket options match checkout inventory and cannot oversell configured capacity.','Needs review','Draft','system',1795587116912,1795587116912),
  ('ticket-feature-checkin','module-ticketing','Guests and QR check-in','Assign guests and record admission.','Issue unique admission credentials, support safe re-entry policy, and retain check-in history.','Duplicate scans are visible and cannot silently admit the same credential twice.','Needs review','Draft','system',1795587116912,1795587116912),
  ('sponsor-feature-portal','module-sponsors','Sponsor invitation and portal','Secure sponsor response and asset collection.','Use scoped invitation tokens for contacts, commitments, benefits, brand assets, and status.','Expired or unrelated tokens cannot access another sponsor or organization.','Needs review','Draft','system',1795587116912,1795587116912),
  ('live-feature-session','module-gather-live','Operator and projector session','Durable live-event state and public display.','Control readiness, active, paused, and ended states with separate operator and projector experiences.','Permanent authorization or not-found failures stop projector polling and provide a safe exit.','Needs review','Draft','system',1795587116912,1795587116912),
  ('live-feature-appeal','module-gather-live','Fund-a-Need and paddles','Capture recognized pledges during the event.','Support paddle identity, giving levels, custom amounts, operator confirmation, and payment handoff.','Every accepted pledge has one supporter, one event, an auditable source, and a reconciliation status.','Needs review','Draft','system',1795587116912,1795587116912),
  ('offer-feature-public','module-direct-offers','Direct offer page and purchase','Public offer terms and nonprofit-attributed conversion.','Present approved package content and route a paid purchase into the established travel claim lifecycle.','No unpaid or duplicate purchase creates fulfillment.','Needs review','Draft','system',1795587116912,1795587116912),
  ('message-feature-threads','module-messaging','Organization and event threads','Scoped conversations with unread state.','Authorize every participant, preserve chronology, and support moderation and notification preferences.','Cross-organization thread access is denied.','Needs review','Draft','system',1795587116912,1795587116912),
  ('settings-feature-receipts','module-org-settings','Email and receipt settings','Editable organization-wide sender and receipt content.','Separate authentication email from organization contact and verified sender identities.','Changes are auditable and never expose provider credentials.','Needs review','Draft','system',1795587116912,1795587116912),
  ('security-feature-audit','module-security-records','Immutable audit trail','Append-only evidence for material actions.','Capture actor, organization, action, target, timestamp, and before/after metadata with retention controls.','Protected audit events cannot be updated or deleted through ordinary application paths.','Needs review','Draft','system',1795587116912,1795587116912),
  ('sandbox-feature-isolation','module-sandbox-testing','Fail-closed environment isolation','Reject production credentials and real-world side effects in staging.','Validate Supabase, D1, Stripe, email, URLs, and fulfillment mode before the application starts.','Unsafe cross-environment configuration fails closed and reports the exact invalid boundary.','Needs review','Draft','system',1795587116912,1795587116912),
  ('sandbox-feature-fixtures','module-sandbox-testing','Persistent test roles and fixtures','Reusable organizations, events, supporters, auctions, invoices, and travel records.','Seed deterministic staging-only identities and records without production personal data.','Authorized testers can exercise core flows without recreating baseline data each session.','Needs review','Draft','system',1795587116912,1795587116912);

INSERT OR IGNORE INTO planner_project_goals
  (id,name,description,approved_scope,completion_criteria,target_milestones,baseline_version,approval_state,approved_at,scoring_version,created_by,created_at,updated_at)
VALUES
  ('goal-production-ready-gather','Production-ready Gather platform','Review the complete Gather module inventory, approve the launch scope, then measure progress only from evidence-backed tasks.','[]','[]','[]',1,'Draft',NULL,'gather-evidence-v1','system',1795587116912,1795587116912);
